import 'package:flutter/material.dart';
import 'package:shared_preferences/shared_preferences.dart';
class MentorScreen extends StatefulWidget{const MentorScreen({super.key});@override State<MentorScreen> createState()=>_MentorScreenState();}
class _MentorScreenState extends State<MentorScreen>{
 final input=TextEditingController();String name='Aspirant',exam='Exam',language='Bengali';double hours=3;List<String> weak=[];int correct=0,total=0,mistakes=0;final messages=<Map<String,String>>[];
 @override void initState(){super.initState();load();}
 Future<void> load()async{final p=await SharedPreferences.getInstance();name=p.getString('name')??'Aspirant';exam=p.getString('exam')??'Exam';language=p.getString('language')??'Bengali';hours=p.getDouble('daily_hours')??3;final selected=p.getStringList('weak_subjects')??[];final detected=p.getStringList('detected_weak_subjects')??[];weak=[...detected,...selected.where((x)=>!detected.contains(x))];correct=p.getInt('last_mock_correct')??0;total=p.getInt('last_mock_total')??0;mistakes=(p.getStringList('mistake_book')??[]).length;if(mounted)setState(()=>messages.add({'role':'mentor','text':greeting()}));}
 int get accuracy=>total==0?0:(correct/total*100).round();
 String greeting(){final w=weak.isEmpty?'Math':weak.first;return language=='Bengali'?name+', AgenticAI V2 ready। '+exam+'-এর performance data দেখে priority: '+w+'। শেষ mock accuracy: '+accuracy.toString()+'%। কী নিয়ে সাহায্য চাই?':name+', AgenticAI V2 is ready. For '+exam+' your priority is '+w+'. Last mock accuracy: '+accuracy.toString()+'%. What should we work on?';}
 String reply(String q){final s=q.toLowerCase(),w=weak.isEmpty?'Math':weak.first;final mins=(hours*60).round();if(s.contains('plan')||s.contains('today')||s.contains('আজ')){final a=(mins*.4).round(),b=(mins*.35).round(),c=mins-a-b;return language=='Bengali'?'আজ '+w+': '+a.toString()+' মিনিট concept/PYQ, '+b.toString()+' মিনিট timed practice, '+c.toString()+' মিনিট Mistake Book।':'Today: '+w+' — '+a.toString()+' min concept/PYQ, '+b.toString()+' min timed practice, '+c.toString()+' min Mistake Book.';}if(s.contains('mock')||s.contains('score')||s.contains('accuracy'))return 'Last mock: '+correct.toString()+'/'+total.toString()+' correct • '+accuracy.toString()+'% accuracy. '+(accuracy<60?'Repair accuracy before speed.':accuracy<80?'Prioritise timed PYQ and error review.':'Increase full mocks, speed and spaced revision.');if(s.contains('mistake')||s.contains('ভুল'))return 'Mistake Book: '+mistakes.toString()+' revision targets. Re-solve '+w+' mistakes first.';if(s.contains('weak')||s.contains('দুর্বল'))return 'Weak priority from mock + profile: '+(weak.isEmpty?'not enough data yet':weak.join(', '))+'.';return language=='Bengali'?exam+' data অনুযায়ী এখন সবচেয়ে দরকার: '+w+' practice → ভুল review → timed PYQ। Plan/Mock/Weak/Mistake লিখে analysis নাও।':'Best next action for '+exam+': '+w+' practice → mistake review → timed PYQ. Ask about Plan, Mock, Weak or Mistake.';}
 void send(){final q=input.text.trim();if(q.isEmpty)return;setState(()=>messages.add({'role':'user','text':q}));input.clear();setState(()=>messages.add({'role':'mentor','text':reply(q)}));}
 @override void dispose(){input.dispose();super.dispose();}
 @override Widget build(BuildContext context)=>Column(children:[Padding(padding:const EdgeInsets.fromLTRB(20,20,20,8),child:Row(children:[const CircleAvatar(child:Icon(Icons.auto_awesome_rounded)),const SizedBox(width:12),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Adaptive Mentor V2',style:Theme.of(context).textTheme.titleLarge?.copyWith(fontWeight:FontWeight.w800)),Text(exam+' • '+accuracy.toString()+'% accuracy')]))])),Expanded(child:ListView.builder(padding:const EdgeInsets.all(16),itemCount:messages.length,itemBuilder:(c,i){final m=messages[i],mine=m['role']=='user';return Align(alignment:mine?Alignment.centerRight:Alignment.centerLeft,child:Container(constraints:const BoxConstraints(maxWidth:330),margin:const EdgeInsets.only(bottom:10),padding:const EdgeInsets.all(14),decoration:BoxDecoration(color:mine?Theme.of(context).colorScheme.primaryContainer:Theme.of(context).colorScheme.surfaceContainerHighest,borderRadius:BorderRadius.circular(18)),child:Text(m['text']!)));})),SafeArea(top:false,child:Padding(padding:const EdgeInsets.all(12),child:Row(children:[Expanded(child:TextField(controller:input,onSubmitted:(_)=>send(),decoration:const InputDecoration(hintText:'Ask about plan, mock, weak, mistake...',border:OutlineInputBorder()))),const SizedBox(width:8),IconButton.filled(onPressed:send,icon:const Icon(Icons.send_rounded))])))]);
}
